export interface Ball {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
}

export interface SimConfig {
  gravity: number;
  bounce: number;
  friction: number;
  ballSize: number;
}

export interface ControlsProps {
  config: SimConfig;
  onChangeConfig: (newConfig: SimConfig) => void;
  onClearBalls: () => void;
  onSpawnBatch: () => void;
  isPaused: boolean;
  onTogglePause: () => void;
  ballCount: number;
}

export interface PhysicsCanvasProps {
  config: SimConfig;
  isPaused: boolean;
  onUpdateCount: (count: number) => void;
  clearTrigger?: number;
  spawnBatchTrigger?: number;
}

import { useRef, useEffect, useCallback, PointerEvent } from 'react';
import { Ball, PhysicsCanvasProps } from '../types';

const BALL_COLORS = [
  '#ef4444',
  '#f97316',
  '#f59e0b',
  '#10b981',
  '#06b6d4',
  '#3b82f6',
  '#8b5cf6',
  '#ec4899',
];

interface DragState {
  isDragging: boolean;
  startX: number;
  startY: number;
  currentX: number;
  currentY: number;
}

export default function PhysicsCanvas({
  config,
  isPaused,
  onUpdateCount,
  clearTrigger = 0,
  spawnBatchTrigger = 0,
}: PhysicsCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const ballsRef = useRef<Ball[]>([]);
  const nextIdRef = useRef<number>(1);
  const dragRef = useRef<DragState>({
    isDragging: false,
    startX: 0,
    startY: 0,
    currentX: 0,
    currentY: 0,
  });

  const configRef = useRef(config);
  configRef.current = config;

  const isPausedRef = useRef(isPaused);
  isPausedRef.current = isPaused;

  const prevClearTriggerRef = useRef(clearTrigger);
  const prevSpawnBatchTriggerRef = useRef(spawnBatchTrigger);

  const getRandomColor = () => {
    return BALL_COLORS[Math.floor(Math.random() * BALL_COLORS.length)];
  };

  const createBall = useCallback(
    (x: number, y: number, vx?: number, vy?: number, customRadius?: number, customColor?: string): Ball => {
      const radius = customRadius ?? configRef.current.ballSize;
      const id = nextIdRef.current++;
      return {
        id,
        x,
        y,
        vx: vx !== undefined ? vx : (Math.random() - 0.5) * 8,
        vy: vy !== undefined ? vy : -Math.random() * 6 - 2,
        radius,
        color: customColor || getRandomColor(),
      };
    },
    []
  );

  // 初回5個生成
  useEffect(() => {
    const canvas = canvasRef.current;
    const width = canvas ? canvas.width : 800;
    const height = canvas ? canvas.height : 500;

    const initialBalls: Ball[] = [];
    for (let i = 0; i < 5; i++) {
      const radius = 16 + i * 4;
      const x = (width / 6) * (i + 1);
      const y = height * 0.3 + (i % 2) * 50;
      initialBalls.push({
        id: nextIdRef.current++,
        x,
        y,
        vx: (Math.random() - 0.5) * 6,
        vy: (Math.random() - 0.5) * 4,
        radius,
        color: BALL_COLORS[i % BALL_COLORS.length],
      });
    }
    ballsRef.current = initialBalls;
    onUpdateCount?.(initialBalls.length);
  }, [onUpdateCount]);

  // 全消去トリガー
  useEffect(() => {
    if (clearTrigger !== prevClearTriggerRef.current) {
      prevClearTriggerRef.current = clearTrigger;
      ballsRef.current = [];
      onUpdateCount?.(0);
    }
  }, [clearTrigger, onUpdateCount]);

  // 10個追加トリガー
  useEffect(() => {
    if (spawnBatchTrigger !== prevSpawnBatchTriggerRef.current) {
      prevSpawnBatchTriggerRef.current = spawnBatchTrigger;
      const canvas = canvasRef.current;
      const width = canvas ? canvas.width : 800;
      const height = canvas ? canvas.height : 500;
      const newBalls: Ball[] = [];

      for (let i = 0; i < 10; i++) {
        const radius = Math.max(10, configRef.current.ballSize + (Math.random() * 12 - 6));
        const x = Math.random() * (width - radius * 2) + radius;
        const y = Math.random() * (height * 0.4) + radius;
        newBalls.push(createBall(x, y, (Math.random() - 0.5) * 10, (Math.random() - 0.5) * 5, radius));
      }

      ballsRef.current = [...ballsRef.current, ...newBalls];
      onUpdateCount?.(ballsRef.current.length);
    }
  }, [spawnBatchTrigger, createBall, onUpdateCount]);

  // メインループ
  useEffect(() => {
    let animId: number;

    const updatePhysics = (width: number, height: number) => {
      if (isPausedRef.current) return;

      const currentConfig = configRef.current;
      const g = currentConfig.gravity * 0.6;
      const restitution = currentConfig.bounce;
      const friction = Math.max(0, 1 - currentConfig.friction);
      const balls = ballsRef.current;
      const len = balls.length;

      // 移動と重力
      for (let i = 0; i < len; i++) {
        const b = balls[i];
        b.vy += g;
        b.vx *= friction;
        b.vy *= friction;
        b.x += b.vx;
        b.y += b.vy;

        // 床衝突
        if (b.y + b.radius >= height) {
          b.y = height - b.radius;
          b.vy = -b.vy * restitution;
          b.vx *= 0.95; // 床との接触摩擦
          if (Math.abs(b.vy) < 0.2 && Math.abs(g) > 0.01) {
            b.vy = 0;
          }
        }

        // 天井衝突
        if (b.y - b.radius <= 0) {
          b.y = b.radius;
          b.vy = -b.vy * restitution;
        }

        // 壁衝突
        if (b.x + b.radius >= width) {
          b.x = width - b.radius;
          b.vx = -b.vx * restitution;
        } else if (b.x - b.radius <= 0) {
          b.x = b.radius;
          b.vx = -b.vx * restitution;
        }
      }

      // ボール同士の簡易弾性衝突 (円形衝突)
      for (let i = 0; i < len; i++) {
        for (let j = i + 1; j < len; j++) {
          const b1 = balls[i];
          const b2 = balls[j];
          const dx = b2.x - b1.x;
          const dy = b2.y - b1.y;
          const dist = Math.hypot(dx, dy);
          const minDist = b1.radius + b2.radius;

          if (dist < minDist && dist > 0.0001) {
            const nx = dx / dist;
            const ny = dy / dist;

            // 重なり解消
            const overlap = (minDist - dist) * 0.5;
            b1.x -= nx * overlap;
            b1.y -= ny * overlap;
            b2.x += nx * overlap;
            b2.y += ny * overlap;

            // 相対速度
            const kx = b1.vx - b2.vx;
            const ky = b1.vy - b2.vy;
            const p = 2 * (nx * kx + ny * ky) / 2; // 質量比1:1の簡易計算

            b1.vx -= p * nx * restitution;
            b1.vy -= p * ny * restitution;
            b2.vx += p * nx * restitution;
            b2.vy += p * ny * restitution;
          }
        }
      }
    };

    const render = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const width = canvas.width;
      const height = canvas.height;

      updatePhysics(width, height);

      // 背景クリア
      ctx.clearRect(0, 0, width, height);

      // ボール描画
      const balls = ballsRef.current;
      for (let i = 0; i < balls.length; i++) {
        const b = balls[i];

        // 影
        ctx.save();
        ctx.beginPath();
        const shadowScale = Math.max(0.1, 1 - (height - (b.y + b.radius)) / height);
        ctx.ellipse(
          b.x,
          height - 4,
          Math.max(2, b.radius * shadowScale),
          Math.max(1, (b.radius * 0.3) * shadowScale),
          0,
          0,
          Math.PI * 2
        );
        ctx.fillStyle = 'rgba(0, 0, 0, 0.15)';
        ctx.fill();
        ctx.restore();

        // 本体
        ctx.save();
        ctx.beginPath();
        ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
        ctx.fillStyle = b.color;
        ctx.fill();

        // 立体的なハイライトグラデーション
        const grad = ctx.createRadialGradient(
          b.x - b.radius * 0.3,
          b.y - b.radius * 0.3,
          b.radius * 0.1,
          b.x,
          b.y,
          b.radius
        );
        grad.addColorStop(0, 'rgba(255, 255, 255, 0.6)');
        grad.addColorStop(0.5, 'rgba(255, 255, 255, 0)');
        grad.addColorStop(1, 'rgba(0, 0, 0, 0.25)');
        ctx.fillStyle = grad;
        ctx.fill();

        ctx.strokeStyle = 'rgba(0,0,0,0.1)';
        ctx.lineWidth = 1;
        ctx.stroke();
        ctx.restore();
      }

      // ドラッグ中の射出ガイド線
      const drag = dragRef.current;
      if (drag.isDragging) {
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(drag.startX, drag.startY);
        ctx.lineTo(drag.currentX, drag.currentY);
        ctx.strokeStyle = '#3b82f6';
        ctx.lineWidth = 3;
        ctx.setLineDash([6, 4]);
        ctx.stroke();

        // 始点と終点のマーカー
        ctx.setLineDash([]);
        ctx.beginPath();
        ctx.arc(drag.startX, drag.startY, configRef.current.ballSize, 0, Math.PI * 2);
        ctx.strokeStyle = '#3b82f6';
        ctx.fillStyle = 'rgba(59, 130, 246, 0.2)';
        ctx.fill();
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(drag.currentX, drag.currentY, 5, 0, Math.PI * 2);
        ctx.fillStyle = '#ef4444';
        ctx.fill();
        ctx.restore();
      }

      animId = requestAnimationFrame(render);
    };

    animId = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animId);
  }, []);

  const getCanvasCoords = (e: PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY,
    };
  };

  const handlePointerDown = (e: PointerEvent<HTMLCanvasElement>) => {
    const { x, y } = getCanvasCoords(e);
    dragRef.current = {
      isDragging: true,
      startX: x,
      startY: y,
      currentX: x,
      currentY: y,
    };
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: PointerEvent<HTMLCanvasElement>) => {
    if (!dragRef.current.isDragging) return;
    const { x, y } = getCanvasCoords(e);
    dragRef.current.currentX = x;
    dragRef.current.currentY = y;
  };

  const handlePointerUp = (e: PointerEvent<HTMLCanvasElement>) => {
    if (!dragRef.current.isDragging) return;
    const { x, y } = getCanvasCoords(e);
    const startX = dragRef.current.startX;
    const startY = dragRef.current.startY;
    dragRef.current.isDragging = false;

    try {
      (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    } catch {
      // safe fallback
    }

    const dx = x - startX;
    const dy = y - startY;
    const dist = Math.hypot(dx, dy);

    let vx = (Math.random() - 0.5) * 6;
    let vy = (Math.random() - 0.5) * 6;

    // 一定量以上ドラッグされていたら射出ベクトルにする
    if (dist > 8) {
      vx = (startX - x) * 0.15;
      vy = (startY - y) * 0.15;
    }

    const newBall = createBall(startX, startY, vx, vy);
    ballsRef.current = [...ballsRef.current, newBall];
    onUpdateCount?.(ballsRef.current.length);
  };

  return (
    <div className="canvas-container">
      <canvas
        ref={canvasRef}
        className="physics-canvas"
        width={800}
        height={500}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
      />
      <div className="canvas-hint">
        画面をクリックまたはドラッグしてボールを追加・射出
      </div>
    </div>
  );
}

import { useState, useCallback } from 'react';
import { SimConfig } from './types';
import Controls from './components/Controls';
import PhysicsCanvas from './components/PhysicsCanvas';

export default function App() {
  const [config, setConfig] = useState<SimConfig>({
    gravity: 0.98,
    bounce: 0.8,
    friction: 0.005,
    ballSize: 20,
  });

  const [isPaused, setIsPaused] = useState<boolean>(false);
  const [ballCount, setBallCount] = useState<number>(5);
  const [clearTrigger, setClearTrigger] = useState<number>(0);
  const [spawnBatchTrigger, setSpawnBatchTrigger] = useState<number>(0);

  const handleClearBalls = useCallback(() => {
    setClearTrigger((prev) => prev + 1);
  }, []);

  const handleSpawnBatch = useCallback(() => {
    setSpawnBatchTrigger((prev) => prev + 1);
  }, []);

  const handleTogglePause = useCallback(() => {
    setIsPaused((prev) => !prev);
  }, []);

  return (
    <div className="sim-app">
      <header className="sim-header">
        <h1 className="sim-title">重力バウンド物理シミュレーション</h1>
        <p className="sim-subtitle">
          画面をクリックまたはタップしてボールを追加。重力・反発係数・摩擦を自由に調整できます。
        </p>
      </header>

      <main className="sim-main">
        <PhysicsCanvas
          config={config}
          isPaused={isPaused}
          onUpdateCount={setBallCount}
          clearTrigger={clearTrigger}
          spawnBatchTrigger={spawnBatchTrigger}
        />
        <Controls
          config={config}
          onChangeConfig={setConfig}
          onClearBalls={handleClearBalls}
          onSpawnBatch={handleSpawnBatch}
          isPaused={isPaused}
          onTogglePause={handleTogglePause}
          ballCount={ballCount}
        />
      </main>
    </div>
  );
}
